// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(uint256 depositAmount, uint256 withdrawalAmount) public {
        depositAmount = bound(depositAmount, 1, type(uint256).max / 2);
        withdrawalAmount = bound(withdrawalAmount, 1, depositAmount);

        address sender = address(0x1234);

        vm.deal(sender, depositAmount);
        vm.prank(sender);
        c.addToBalance{value: depositAmount}();

        uint256 balanceBefore = c.getBalance(sender);
        require(balanceBefore > 0, "deposit failed");

        vm.prank(sender);
        c.withdrawBalance();

        assert(c.getBalance(sender) == 0);
    }
}
